import { build } from "vite";
import { access, mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const web = path.join(root, "web");
// Mermaid payload is normally generated by P1.  Reuse the checked generated
// source when it is already present so this web-only build never traverses the
// prototype's ignored vendor directory.
try { await access(path.join(root, "src", "generated", "mermaidEditorDocument.ts")); } catch { await import(pathToFileURL(path.join(root, "scripts", "build-mermaid-editor.mjs")).href); }
await import(pathToFileURL(path.join(root, "scripts", "build-html-export-browser.mjs")).href);
await build({
  configFile: path.join(web, "vite.config.ts"),
  logLevel: "info",
});
let html = await readFile(path.join(web, "dist", "index.html"), "utf8");
const css = html.match(/<link rel="stylesheet"[^>]*href="([^"]+)"[^>]*>/)?.[1];
const js = html.match(/<script type="module"[^>]*src="([^"]+)"[^>]*><\/script>/)?.[1];
if (!css || !js) throw new Error("Web build assets were not found.");
const [style, script] = await Promise.all([readFile(path.join(web, "dist", css), "utf8"), readFile(path.join(web, "dist", js), "utf8")]);
html = html.replace(/<link rel="stylesheet"[^>]*>/, () => `<style>${style}</style>`).replace(/<script type="module"[^>]*><\/script>/, () => `<script type="module">${script.replace(/<\/script/gi, "<\\/script")}</script>`);
// バンドル内にもMermaidエディターの<body>文字列が含まれる。
// 最初の一致を書き換えるとJS文字列に生の</script>が混ざり、PHP版だけ壊れる。
const bodyOffset = html.lastIndexOf('<body>');
if (bodyOffset < 0) throw new Error('Webアプリのbody開始位置を取得できません。');
const phpHtml = html.slice(0, bodyOffset + 6) + '<script>window.__MDVISUALIZER_PHP__=true;</script>' + html.slice(bodyOffset + 6);
for (const [target, content] of [[path.join(root, "release", "web", "mdvisualizer.html"), html], [path.join(web, "php", "app.html"), phpHtml]]) { await mkdir(path.dirname(target), { recursive: true }); await writeFile(target, content, "utf8"); }
console.log("Web single-file builds written to release/web and web/php.");
